import {ssrSafeWindow} from '@github-ui/ssr-utils'
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton, useRefObjectAsForwardedRef} from '@primer/react'
import {forwardRef, useRef} from 'react'

import {Resources} from '../constants/strings'
import type {IssueType} from '../types/issue-type'

type IssueTypeItemMenuProps = {
  issueType: IssueType
  owner?: string
  toggleIssueType: () => void
  handleDelete: () => void
}

export const IssueTypeItemMenu = forwardRef<HTMLElement, IssueTypeItemMenuProps>(
  ({issueType, owner, toggleIssueType, handleDelete}, forwardedRef) => {
    const handleSelect = () => {
      if (ssrSafeWindow) ssrSafeWindow.location.href = `/organizations/${owner}/settings/issue-types/${issueType.id}`
    }

    const ref = useRef<HTMLElement | null>(null)
    useRefObjectAsForwardedRef(forwardedRef, ref)

    return (
      <ActionMenu anchorRef={ref}>
        <ActionMenu.Anchor>
          <IconButton
            data-testid="overflow-menu-anchor"
            aria-label={`Open type options for ${issueType.name}`}
            variant="invisible"
            icon={KebabHorizontalIcon}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            <ActionList.Item onSelect={handleSelect}>{Resources.editButton}</ActionList.Item>
            <ActionList.Item data-testid={`menu-enable-option-${issueType.id}`} onSelect={toggleIssueType}>
              {issueType.isEnabled ? Resources.disableButton : Resources.enableButton}
            </ActionList.Item>
            <ActionList.Divider />
            <ActionList.Item
              data-testid={`menu-delete-option-${issueType.id}`}
              onSelect={handleDelete}
              variant="danger"
            >
              {Resources.deleteButton}
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    )
  },
)

IssueTypeItemMenu.displayName = 'IssueTypeItemMenu'
