import {Dialog} from '@primer/react/experimental'
import {useCallback} from 'react'

import {Resources} from '../constants/strings'
import {useEnableDisableIssueType} from '../hooks/use-enable-disable-issue-type'
import {useIssueTypesAnalytics} from '../hooks/use-issue-types-analytics'
import type {IssueType} from '../types/issue-type'
import type {SetA11yAnnouncement} from '../types/shared-types'
import styles from './DisableOrganizationConfirmationDialog.module.css'

interface DisableOrganizationConfirmationDialogProps {
  owner: string
  issueType: IssueType
  closeDialog: () => void
  returnFocusRefDisable?: React.RefObject<HTMLElement | null>
  setA11yAnnouncement?: SetA11yAnnouncement
}

export const DisableOrganizationConfirmationDialog = ({
  owner,
  issueType,
  closeDialog,
  returnFocusRefDisable,
  setA11yAnnouncement,
}: DisableOrganizationConfirmationDialogProps) => {
  const {id, name} = issueType
  const {sendIssueTypesAnalyticsEvent} = useIssueTypesAnalytics()

  const handleSuccess = useCallback(() => {
    setA11yAnnouncement?.(Resources.disabledIssueTypeSuccess)
  }, [setA11yAnnouncement])

  const handleCloseDialog = useCallback(() => {
    setA11yAnnouncement?.(null)
    closeDialog()
  }, [setA11yAnnouncement, closeDialog])

  const {disableOrganizationIssueType} = useEnableDisableIssueType(owner, handleSuccess)

  const handleConfirmClick = useCallback(() => {
    handleCloseDialog()
    sendIssueTypesAnalyticsEvent('org_issue_type.disable', 'ORG_ISSUE_TYPE_DISABLE_BUTTON', {issueTypeId: id})
    disableOrganizationIssueType(id)
  }, [disableOrganizationIssueType, id, sendIssueTypesAnalyticsEvent, handleCloseDialog])

  return (
    <Dialog
      onClose={handleCloseDialog}
      title={Resources.disableConfirmationDialogHeader}
      footerButtons={[
        {buttonType: 'default', content: Resources.cancelButton, onClick: handleCloseDialog},
        {
          buttonType: 'primary',
          onClick: handleConfirmClick,
          content: Resources.disableButton,
        },
      ]}
      className={styles.DisableOrganizationConfirmationDialogContainer}
      returnFocusRef={returnFocusRefDisable}
    >
      <span>{Resources.disableConfirmationDialogBody(name)}</span>
    </Dialog>
  )
}

try{ DisableOrganizationConfirmationDialog.displayName ||= 'DisableOrganizationConfirmationDialog' } catch {}