import {type DefaultError, useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'

import type {IssueType, IssueTypeColor} from '../types/issue-type'

export type UpdateIssueTypeMutationInput = {
  issueTypeId: string
  name?: string
  color?: IssueTypeColor
  description?: string
  isEnabled?: boolean
  pinnedIssueFieldIds?: string[]
}

export type UpdateIssueTypeMutationResult = IssueType | {errors: string[]}

export function useUpdateIssueTypeMutation({
  owner,
  onError,
  onSuccess,
}: {
  owner: string
  onError: (error: Error, variables: UpdateIssueTypeMutationInput) => void
  onSuccess: (data: UpdateIssueTypeMutationResult, variables: UpdateIssueTypeMutationInput) => void
}) {
  return useMutation<UpdateIssueTypeMutationResult, DefaultError, UpdateIssueTypeMutationInput>({
    onError,
    onSuccess,
    mutationFn: async (payload: UpdateIssueTypeMutationInput) => {
      const {issueTypeId, name, description, isEnabled, color, pinnedIssueFieldIds} = payload
      const pathname = `/organizations/${owner}/settings/issue-types/${issueTypeId}`

      const formData = new FormData()
      formData.append('id', issueTypeId)
      if (name) {
        formData.append('name', name)
      }
      if (isEnabled !== undefined) {
        formData.append('is_enabled', isEnabled.toString())
      }
      if (description) {
        formData.append('description', description)
      }
      if (color) {
        formData.append('color', color)
      }
      if (pinnedIssueFieldIds) {
        formData.append('pinned_issue_field_ids', JSON.stringify(pinnedIssueFieldIds))
      }

      const response = await reactFetch(pathname, {
        method: 'PATCH',
        body: formData,
      })

      return (await response.json()) as UpdateIssueTypeMutationResult
    },
  })
}
