import {ssrSafeWindow} from '@github-ui/ssr-utils'
import {useCallback} from 'react'

import {Resources} from '../constants/strings'
import {useIssueTypesMutationErrorsContext} from '../contexts/IssueTypesMutationErrorsContext'
import {type DeleteIssueTypeMutationResult, useDeleteIssueTypeMutation} from '../mutations/delete-issue-type-mutation'
import {formatError} from '../utils'

export const useDeleteIssueType = (owner: string, onDone?: () => void, redirect = true) => {
  const {setMutationError, clearError} = useIssueTypesMutationErrorsContext()
  const deleteIssueTypeMutation = useDeleteIssueTypeMutation({
    owner,
    onError: () => {
      setMutationError(Resources.deletedIssueTypeError)
      onDone?.()
    },
    onSuccess: (data: DeleteIssueTypeMutationResult) => {
      if ('errors' in data) {
        data.errors.map(e => reportError(formatError('DeleteIssueType', e)))
        setMutationError(Resources.deletedIssueTypeError)
      } else {
        if (redirect && ssrSafeWindow) {
          ssrSafeWindow.location.href = `/organizations/${owner}/settings/issue-types`
        }
      }
      onDone?.()
    },
  })

  const deleteIssueType = useCallback(
    async (issueTypeId: string) => {
      clearError()

      await deleteIssueTypeMutation.mutateAsync({
        issueTypeId,
      })
    },
    [clearError, deleteIssueTypeMutation],
  )

  return {
    deleteIssueType,
  }
}
