import {DragAndDrop} from '@github-ui/drag-and-drop'
import {type IssueField, toIssueFieldType} from '@github-ui/issue-fields-shared/issue-field'
import type {IssueField as IssueFieldPickerField} from '@github-ui/item-picker/IssueFieldPicker'
import {IssueFieldPicker} from '@github-ui/item-picker/IssueFieldPicker'
import {PlusIcon} from '@primer/octicons-react'
import {Heading, IconButton} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {type Dispatch, type SetStateAction, useCallback, useMemo} from 'react'

import {MAX_PINNED_FIELDS} from '../constants/constants'
import {Resources} from '../constants/strings'
import {PinnedIssueFieldItem} from './PinnedIssueFieldItem'
import styles from './PinnedIssueFields.module.css'

export type PinnedIssueFieldProps = {
  owner: string
  pinnedIssueFields: IssueField[]
  setPinnedIssueFields: Dispatch<SetStateAction<IssueField[]>>
}

export const PinnedIssueFields = ({owner, pinnedIssueFields, setPinnedIssueFields}: PinnedIssueFieldProps) => {
  const maxReached = pinnedIssueFields.length >= MAX_PINNED_FIELDS
  const notice = maxReached
    ? {
        text: Resources.maxPinnedIssuesWarning(MAX_PINNED_FIELDS),
        variant: 'warning' as const,
      }
    : undefined

  const addIssueFieldAnchor = useMemo(() => {
    // eslint-disable-next-line react/display-name
    return (anchorProps: React.HTMLAttributes<HTMLElement>, ref?: React.RefObject<HTMLButtonElement | null>) => {
      return (
        <IconButton
          onClick={event => {
            anchorProps.onClick?.(event)
          }}
          ref={ref}
          icon={PlusIcon}
          variant="default"
          aria-label={
            maxReached ? Resources.maxPinnedIssuesLabel(MAX_PINNED_FIELDS) : Resources.addPinnedIssueFieldsLabel
          }
          tooltipDirection="n"
          inactive={maxReached}
        />
      )
    }
  }, [maxReached])

  const onUnpin = useCallback(
    (id: string) => {
      const pinnedFields = pinnedIssueFields.filter(field => field.id !== id)
      setPinnedIssueFields(pinnedFields)
    },
    [pinnedIssueFields, setPinnedIssueFields],
  )

  const handleDrop = ({
    dragMetadata,
    dropMetadata,
    isBefore,
  }: {
    dragMetadata: {id: string}
    dropMetadata: {id: string}
    isBefore: boolean
  }) => {
    const dragIndex = pinnedIssueFields.findIndex(opt => opt.id === dragMetadata.id)
    const dropIndex = pinnedIssueFields.findIndex(opt => opt.id === dropMetadata.id)

    if (dragIndex === -1 || dropIndex === -1) return

    const newOptions = [...pinnedIssueFields]
    const [draggedItem] = newOptions.splice(dragIndex, 1)

    if (draggedItem) {
      // Adjust the drop index if the dragged item was before the drop target
      const adjustedDropIndex = dragIndex < dropIndex ? dropIndex - 1 : dropIndex
      const insertIndex = isBefore ? adjustedDropIndex : adjustedDropIndex + 1
      newOptions.splice(insertIndex, 0, draggedItem)
    }

    setPinnedIssueFields(newOptions)
  }

  return (
    <div className={styles.PinnedIssueFieldsContainer}>
      <>
        <div className={styles.PinnedIssueFieldsHeader}>
          <div className={styles.PinnedIssueFieldsHeaderHeadings}>
            <Heading as="h3" className={styles.PinnedIssueFieldsHeading}>
              {Resources.pinnedIssueFieldsLabel}
            </Heading>
            <p className={styles.PinnedIssueFieldsDescription}>{Resources.pinnedIssueFieldsDescription}</p>
          </div>
          <IssueFieldPicker
            owner={owner}
            title={Resources.pinnedIssueFieldPickerLabel}
            fieldsSet={pinnedIssueFields.map(field => field.name)}
            onSelectionChange={(fields: IssueFieldPickerField[]) => {
              if (maxReached) return
              const field = fields[0]
              if (field && field.id && field.name && field.dataType) {
                const selectedField: IssueField = {
                  id: field.databaseId?.toString() || '',
                  name: field.name,
                  type: toIssueFieldType(field.dataType),
                  description: '',
                }
                setPinnedIssueFields(current => [...current, selectedField])
              }
            }}
            anchorElement={addIssueFieldAnchor}
            insidePortal={false}
            notice={notice}
          />
        </div>
        {pinnedIssueFields.length === 0 ? (
          <div className={styles.PinnedIssueFieldsBlankSlate}>
            <Blankslate border size="small">
              <Blankslate.Heading>{Resources.pinnedIssueFieldsBlankslateHeading}</Blankslate.Heading>
              <Blankslate.Description>{Resources.pinnedIssueFieldsBlankslateBody}</Blankslate.Description>
            </Blankslate>
          </div>
        ) : (
          <div className={styles.PinnedIssueFieldsListContainer}>
            <DragAndDrop
              items={pinnedIssueFields.map(option => {
                return {id: option.id, title: option.name, option}
              })}
              onDrop={handleDrop}
              style={{listStyle: 'none'}}
              aria-label={Resources.pinnedIssueFieldsAriaLabel}
              renderOverlay={({option}, index) => (
                <DragAndDrop.Item
                  id={option.id}
                  index={index}
                  title={option.name}
                  key={option.id}
                  hideTrigger
                  isDragOverlay
                >
                  <PinnedIssueFieldItem option={option} index={index} onUnpin={onUnpin} />
                </DragAndDrop.Item>
              )}
            >
              {pinnedIssueFields.map((option, index) => (
                <DragAndDrop.Item id={option.id} index={index} title={option.name} key={option.id} hideTrigger>
                  <PinnedIssueFieldItem option={option} index={index} onUnpin={onUnpin} />
                </DragAndDrop.Item>
              ))}
            </DragAndDrop>
          </div>
        )}
      </>
    </div>
  )
}

try{ PinnedIssueFields.displayName ||= 'PinnedIssueFields' } catch {}