import {AnalyticsProvider} from '@github-ui/analytics-provider'
// eslint-disable-next-line no-restricted-imports
import {reportError} from '@github-ui/failbot'
import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {type ColorName, colorNames} from '@github-ui/use-named-color'
import {Banner, Label, Link} from '@primer/react'
import {AriaAlert} from '@primer/react/experimental'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {DangerZone} from '../components/DangerZone'
import {PinnedIssueFields} from '../components/PinnedIssueFields'
import {Title} from '../components/Title'
import {TypeColor} from '../components/TypeColor'
import {TypeDescription} from '../components/TypeDescription'
import {TypeName} from '../components/TypeName'
import {TypeSubmissionButtons} from '../components/TypeSubmissionButtons'
import {Resources} from '../constants/strings'
import {useIssueTypesMutationErrorsContext} from '../contexts/IssueTypesMutationErrorsContext'
import {useConfirmationMessage} from '../hooks/use-confirmation-message'
import {useInputFieldsErrors} from '../hooks/use-input-fields-errors'
import {type UpdateIssueTypeMutationResult, useUpdateIssueTypeMutation} from '../mutations/update-issue-type-mutation'
import {formatError} from '../utils'
import {type IssueTypesSettingsEditResponse, issueTypesSettingsEditRoute} from './edit-route'
import styles from './OrganizationIssueTypesSettingsEdit.module.css'

type InputErrors = {
  nameField?: string
  descriptionField?: string
}

export function OrganizationIssueTypesSettingsEdit() {
  const {data: preloadedData} = useRouteQuery(issueTypesSettingsEditRoute, 'mainQuery')
  const analyticsMetadata = {
    owner: preloadedData.organization.login ?? '',
    issueTypeId: preloadedData.issueType.id?.toString() ?? '',
  }

  return (
    <AnalyticsProvider appName="issue_types" category="edit" metadata={analyticsMetadata}>
      <OrganizationIssueTypesSettingsEditInternal preloadedData={preloadedData} />
    </AnalyticsProvider>
  )
}

const OrganizationIssueTypesSettingsEditInternal = ({
  preloadedData,
}: {
  preloadedData: IssueTypesSettingsEditResponse
}) => {
  const data = preloadedData.issueType
  const owner = preloadedData.organization.login
  const pinnedIssueFieldsEnabled = preloadedData.pinnedIssueFieldsEnabled

  const [name, setName] = useState<string>(data.name || '')
  const [description, setDescription] = useState<string>(data.description || '')
  const effectiveColor = useMemo(() => colorNames.find(c => c === data.color) || 'GRAY', [data.color])
  const [color, setColor] = useState<ColorName>(effectiveColor)
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false)
  const [isEdited, setIsEdited] = useState<boolean>(false)
  const currentPinnedIssueFields = useMemo(
    () => (pinnedIssueFieldsEnabled ? preloadedData.pinnedIssueFields : []),
    [pinnedIssueFieldsEnabled, preloadedData.pinnedIssueFields],
  )
  const [pinnedIssueFields, setPinnedIssueFields] = useState<IssueField[]>(currentPinnedIssueFields)
  const {saveConfirmationRef, changesSaved, showConfirmationMessage} = useConfirmationMessage()

  const {mutationError} = useIssueTypesMutationErrorsContext()
  const errorBanner = useRef<HTMLDivElement>(null)

  const existingIssueTypeNames = useMemo(() => {
    return (
      preloadedData.issueTypes
        ?.map(e => {
          if (e.id !== data.id) {
            return e.name
          }
        })
        .filter(n => n !== undefined && n !== null) ?? []
    )
  }, [data.id, preloadedData.issueTypes])

  const {
    typeNameRef,
    typeDescriptionRef,
    nameError,
    setNameError,
    descriptionError,
    setDescriptionError,
    setShouldFocusError,
    validate,
  } = useInputFieldsErrors(existingIssueTypeNames)

  const editMutation = useUpdateIssueTypeMutation({
    owner,
    onSuccess: (result: UpdateIssueTypeMutationResult) => {
      if ('errors' in result && result.errors.length > 0) {
        const inputErrors: InputErrors = {}
        result.errors.map(message => {
          reportError(formatError('UpdateIssueType', message))
          if (message.startsWith('Name')) {
            inputErrors.nameField = message
            setNameError(message)
          } else if (message.startsWith('Description')) {
            inputErrors.descriptionField = message
            setDescriptionError(message)
          }
        })
        setShouldFocusError(true)
      } else {
        showConfirmationMessage(true)
      }
      setIsSubmitting(false)
    },
    onError: () => {
      setIsSubmitting(false)
    },
  })

  const handleUpdate = useCallback(() => {
    const valid = validate()

    if (!valid) {
      setShouldFocusError(true)
      return
    }

    if (!isEdited) {
      // Shows changes saved confirmation when user reverts changes and clicks `Save`
      showConfirmationMessage(true)
      return
    }

    if (isSubmitting) return

    setIsSubmitting(true)

    editMutation.mutateAsync({
      issueTypeId: data.id,
      description,
      name,
      color,
      isEnabled: data.isEnabled,
      pinnedIssueFieldIds: pinnedIssueFields.map(f => f.id),
    })
  }, [
    color,
    data.id,
    data.isEnabled,
    description,
    editMutation,
    isEdited,
    isSubmitting,
    name,
    pinnedIssueFields,
    setShouldFocusError,
    showConfirmationMessage,
    validate,
  ])

  const handleRevert = useCallback(() => {
    setName(data.name)
    setDescription(data.description || '')
    const initialColor = colorNames.find(c => c === data.color)
    setColor(initialColor || 'GRAY')
    setNameError('')
    setDescriptionError('')
    setPinnedIssueFields(currentPinnedIssueFields)
  }, [currentPinnedIssueFields, data.color, data.description, data.name, setDescriptionError, setNameError])

  useEffect(() => {
    const pinnedIssueFieldsChanged =
      pinnedIssueFieldsEnabled &&
      JSON.stringify(pinnedIssueFields.map(f => f.id).sort()) !==
        JSON.stringify(currentPinnedIssueFields.map(f => f.id).sort())
    const isDirty =
      data.name !== name || data.description !== description || data.color !== color || pinnedIssueFieldsChanged
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsEdited(isDirty)
    if (isDirty) {
      showConfirmationMessage(false)
    }
  }, [
    color,
    currentPinnedIssueFields,
    data.color,
    data.description,
    data.name,
    description,
    name,
    pinnedIssueFields,
    pinnedIssueFieldsEnabled,
    showConfirmationMessage,
  ])

  useEffect(() => {
    if (!!mutationError && errorBanner?.current) {
      errorBanner.current.focus()
    }
  }, [mutationError])

  return (
    <div>
      <Title page="edit">
        <Link href={`/organizations/${owner}/settings/issue-types`}>{Resources.settingsPageHeader}</Link>
        {` / ${data.name}`}
        {!data.isEnabled && <Label className={styles.disabledStatusLabel}>Disabled</Label>}
      </Title>
      {!!mutationError && (
        <Banner
          ref={errorBanner}
          title={Resources.errorTitle}
          description={<AriaAlert>{mutationError}</AriaAlert>}
          variant="critical"
          role="alert"
        />
      )}

      <div className={styles.editFormContainer}>
        <TypeName
          disabled={isSubmitting}
          name={name}
          setName={setName}
          error={nameError}
          setError={setNameError}
          ref={typeNameRef}
        />
        <TypeDescription
          disabled={isSubmitting}
          description={description}
          setDescription={setDescription}
          error={descriptionError}
          setError={setDescriptionError}
          ref={typeDescriptionRef}
        />
        <TypeColor color={color} setColor={setColor} />
        {pinnedIssueFieldsEnabled && (
          <PinnedIssueFields
            owner={owner}
            pinnedIssueFields={pinnedIssueFields}
            setPinnedIssueFields={setPinnedIssueFields}
          />
        )}
        <TypeSubmissionButtons
          disabled={isSubmitting}
          confirmLabel={Resources.saveAfterEditingButton}
          cancelLabel={Resources.revertButton}
          onCancel={handleRevert}
          onConfirm={handleUpdate}
          changesSaved={changesSaved}
          ref={saveConfirmationRef}
        />
      </div>
      {/* delete/disable (danger zone) */}
      <DangerZone issueType={data} owner={owner} />
    </div>
  )
}

try{ OrganizationIssueTypesSettingsEdit.displayName ||= 'OrganizationIssueTypesSettingsEdit' } catch {}
try{ OrganizationIssueTypesSettingsEditInternal.displayName ||= 'OrganizationIssueTypesSettingsEditInternal' } catch {}